  if (!inv.id) return
  downloadingId.value = inv.id
  try {
    const res = await axios.get(`api/invoices/download/${inv.id}`)
    if (res.data?.url) {
      window.open(res.data.url, '_blank')
    }
  } catch {
    alert('No hay PDF disponible para esta factura.')
  } finally {
    downloadingId.value = null
  }
}

